INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37311, 'Genesis 34:8', 'Genesis', 34, 8, 'حمور هغه ته وویل: «زما زوی شکیم ستا په لور باندې مین شوی دی. اجازه ورکړئ چې د هغې سره واده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_8.mp3', '', 1761754199, 1761754199),
(37312, 'Genesis 34:9', 'Genesis', 34, 9, 'زمونږ سره خپلوي وکړئ. خپلې لورګانې مونږ ته راکړئ او زمونږ لورګانې خپلو ځانونو ته وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_9.mp3', '', 1761754199, 1761754199),
(37313, 'Genesis 34:10', 'Genesis', 34, 10, 'تاسو کولای شئ چې دلته په دې وطن کې زمونږ سره واوسېږئ او په هرځای کې چې وغواړئ هلته اوسېدلی شئ. ازاد کاروبار په کې وکړئ او د جایداد خاوندان شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_10.mp3', '', 1761754199, 1761754199),
(37314, 'Genesis 34:11', 'Genesis', 34, 11, 'بیا شکیم د دینه پلار او ورونو ته وویل: «په ما باندې دا مهرباني وکړئ او تاسو چې هرڅه وغواړئ زه به یې درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_11.mp3', '', 1761754199, 1761754199),
(37315, 'Genesis 34:12', 'Genesis', 34, 12, 'ماته ووایئ چې کوم سوغاتونه تاسو غواړئ او هرڅومره زیات مهر چې غواړئ هماغه شان یې وټاکئ او تاسو چې هرڅه زما څخه وغواړئ زه به یې درکړم. یوازې دا اجازه راکړئ چې د هغې سره واده وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_12.mp3', '', 1761754199, 1761754199),
(37316, 'Genesis 34:13', 'Genesis', 34, 13, 'د یعقوب زامنو د شکیم او د هغه د پلار حمور په ځواب کې په مکر سره خبرې وکړې، ځکه چې د هغوی خور دینه یې بې‌عزته کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_13.mp3', '', 1761754199, 1761754199),
(37317, 'Genesis 34:14', 'Genesis', 34, 14, 'هغوی ته یې وویل: «مونږ داسې کار نه شو کولای. مونږ نه شو کولای خپله خور هغه چاته ورکړو چې سنت شوی نه وي، ځکه چې دا زمونږ دپاره شرم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_14.mp3', '', 1761754199, 1761754199),
(37318, 'Genesis 34:15', 'Genesis', 34, 15, 'مونږ په یو شرط تاسو سره جوړه کوو چې ستاسو ټول نارینه دې زمونږ په شان سنت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_15.mp3', '', 1761754199, 1761754199),
(37319, 'Genesis 34:16', 'Genesis', 34, 16, 'هغه وخت به خپلې لورګانې تاسو ته درکړو او ستاسو لورګانې به خپلو ځانونو ته وکړو او تاسو سره به یوځای واوسېږو او یو قوم به شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_16.mp3', '', 1761754199, 1761754199),
(37320, 'Genesis 34:17', 'Genesis', 34, 17, 'خو که چېرې زمونږ خبره قبوله نه کړئ او سنت نه شئ، مونږ به خپله خور واخلو او لاړ به شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_17.mp3', '', 1761754199, 1761754199),
(37321, 'Genesis 34:18', 'Genesis', 34, 18, 'دا شرط حمور او د هغه زوی شکیم ته مناسب ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_18.mp3', '', 1761754199, 1761754199),
(37322, 'Genesis 34:19', 'Genesis', 34, 19, 'هغه ځوان د دې کار په سرته رسولو کې ځنډ ونه کړ، ځکه چې هغه د یعقوب په لور باندې مین ؤ. هغه د خپل پلار په کورنۍ کې تر ټولو عزتمن سړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_19.mp3', '', 1761754199, 1761754199),
(37323, 'Genesis 34:20', 'Genesis', 34, 20, 'حمور او د هغه زوی شکیم د ښار دروازې ته چې د غونډې ځای ؤ، لاړل او د ښار د خلکو سره یې خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_20.mp3', '', 1761754199, 1761754199),
(37324, 'Genesis 34:21', 'Genesis', 34, 21, 'هغوی وویل: «دا خلک زمونږ دوستان دي. پرېږدئ چې زمونږ په خاوره کې واوسیږي او کاروبار په کې وکړي. د هغوی دپاره ځمکه پراخه ده. مونږ کولای شو چې د دوی د لورګانو سره ودونه وکړو او دوی کولای شي چې زمونږ د لورګانو سره ودونه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_21.mp3', '', 1761754199, 1761754199),
(37325, 'Genesis 34:22', 'Genesis', 34, 22, 'نو هغوی زمونږ سره یوازې په دې شرط جوړه کوي چې زمونږ سره واوسیږي او راسره یو قوم شي، چې زمونږ ټول نارینه د دوی په شان سنت شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_22.mp3', '', 1761754199, 1761754199),
(37326, 'Genesis 34:23', 'Genesis', 34, 23, 'ایا د هغوی ټولې رمې او پادې او شتمني او د هغوی نور شیان به زمونږ نه شي؟ نو راځئ چې د دوی سره موافقه وکړو چې زمونږ سره واوسیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_23.mp3', '', 1761754199, 1761754199),
(37327, 'Genesis 34:24', 'Genesis', 34, 24, 'ټولو ښاریانو د حمور او د هغه د زوی شکیم وړاندیز قبول کړ او د ښار ټول نارینه سنت شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_24.mp3', '', 1761754199, 1761754199),
(37328, 'Genesis 34:25', 'Genesis', 34, 25, 'په درېمه ورځ چې ټول خلک لا د سنت کېدلو له امله په درد کې وو، د یعقوب دوه زامنو یعنې د دینه ورونو شمعون او لاوي خپلې تورې واخیستلې او بې له دې چې څوک ورباندې پوه شي، ښار ته ننوتل او ټول نارینه یې ووژل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_25.mp3', '', 1761754199, 1761754199),
(37329, 'Genesis 34:26', 'Genesis', 34, 26, 'چې په هغو کې حمور او د هغه زوی شکیم هم شامل وو. هغوی دینه د شکیم د کور څخه واخیستله او لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_26.mp3', '', 1761754199, 1761754199),
(37330, 'Genesis 34:27', 'Genesis', 34, 27, 'د یعقوب نور زامن په مړو باندې راوختل او ښار یې لوټ کړ، ځکه چې د هغوی خور هلته بې‌عزته شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_27.mp3', '', 1761754199, 1761754199),
(37331, 'Genesis 34:28', 'Genesis', 34, 28, 'د هغوی رمې، پادې او خره او هرڅه چې په ښار او پټیو کې وو، هغه یې واخیستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_28.mp3', '', 1761754199, 1761754199),
(37332, 'Genesis 34:29', 'Genesis', 34, 29, 'د هغوی ټوله شتمني یې واخیستله او اولادونه او ښځې یې اسیران کړل او هرڅه چې په کورونو کې وو هغه یې لوټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_29.mp3', '', 1761754199, 1761754199),
(37333, 'Genesis 34:30', 'Genesis', 34, 30, 'یعقوب شمعون او لاوي ته وویل: «تاسو زه د تکلیف سره مخامخ کړم. اوس به کنعانیان، فرزیان او همدارنګه د دې خاورې نور اوسېدونکي زما څخه کرکه کوي. زه ډېر کسان نه لرم او که چېرې هغوی زما په ضد راټول شي او په ما باندې حمله وکړي، زمونږ ټوله کورنۍ به له منځه لاړه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_30.mp3', '', 1761754199, 1761754199),
(37334, 'Genesis 34:31', 'Genesis', 34, 31, 'خو هغوی ځواب ورکړ: «ایا دا لازمه وه چې هغه دې زمونږ د خور سره د یوې بدلمنې په شان چلند وکړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis34_verse_31.mp3', '', 1761754199, 1761754199),
(37335, 'Micah 2:1', 'Micah', 2, 1, 'افسوس ستاسو په حال چې په شپه کې ویښ پراته یئ او بدې نقشې جوړوئ! کله چې سهار شي، نو څنګه چې موقع په لاس درشي، تاسو خپلې بدې نقشې عملي کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_1.mp3', '', 1761754199, 1761754199),
(37336, 'Micah 2:2', 'Micah', 2, 2, 'کله چې ستاسو زړه پټي وغواړي، نو د خلکو پټي په زور نیسئ. کله چې ستاسو زړه کورونه وغواړي، نو تاسو د خلکو کورونه نیسئ. د هېچا کورنۍ یا جایداد په امن کې نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_2.mp3', '', 1761754199, 1761754199),
(37337, 'Micah 2:3', 'Micah', 2, 3, 'څښتن داسې وایي چې زه اراده لرم چې په تاسو باندې یو افت راولم او تاسو به نه شئ کولای چې ځان ورڅخه خلاص کړئ. تاسو به په بلا اخته شئ او نور به په غرور سره نه ګرځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_3.mp3', '', 1761754199, 1761754199),
(37338, 'Micah 2:4', 'Micah', 2, 4, 'کله چې هغه وخت راشي، نو ستاسو دښمنان به تاسو ته پېغور درکوي او هغوی به ستاسو د غم په هکله دا سندره وایي: مونږ بیخي تباه شو څښتن زمونږ نه خپل وطن اخیستی او هغه یې ورکړی هغو خلکو ته دی چې اسیران کړي یو مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_4.mp3', '', 1761754199, 1761754199),
(37339, 'Micah 2:5', 'Micah', 2, 5, 'نو کله چې هغه وخت راورسیږي چې هغه ځمکه بېرته د څښتن قوم ته ورکړل شي، نو په هغې کې به ستاسو د اولادونو هېڅ برخه نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_5.mp3', '', 1761754199, 1761754199),
(37340, 'Micah 2:6', 'Micah', 2, 6, 'خلک ماته وایي: «داسې خبرې مه کوه، مونږ ته وعظ مه کوه. د دې خبرو په هکله تبلیغ مه کوه. خدای به مونږ نه شرموي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_6.mp3', '', 1761754199, 1761754199),
(37341, 'Micah 2:7', 'Micah', 2, 7, 'ایا داسې باید وویل شي، ای د اسراییلو قومه؟ ایا څښتن خپله حوصله له لاسه ورکړې؟ ایا هغه به داسې کارونه کوي؟ ایا څښتن د هغه چا سره چې نېک کارونه کوي، په مهربانۍ سره خبرې نه کوي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_7.mp3', '', 1761754199, 1761754199),
(37342, 'Micah 2:8', 'Micah', 2, 8, 'خو څښتن هغو خلکو ته په ځواب کې وایي: «تاسو زما په قوم باندې د دښمن په شان حمله کوئ. کوم خلک چې د جنګ نه راروان وي، هغوی فکر کوي چې په کور کې خوندي دي، خو تاسو ورته هلته د دې انتظار کوئ چې کورتۍ‌ګانې ورڅخه غلا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_8.mp3', '', 1761754199, 1761754199),
(37343, 'Micah 2:9', 'Micah', 2, 9, 'تاسو زما د قوم ښځې د خپلو ښایسته کورونو څخه شړئ او د هغوی اولادونه په دې نړۍ کې زما د برکتونو څخه د تل دپاره بې‌برخې کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_9.mp3', '', 1761754199, 1761754199),
(37344, 'Micah 2:10', 'Micah', 2, 10, 'پاڅېږئ او لاړ شئ، په دې وطن کې نور امن نشته. ځکه چې ستاسو د ګناهونو په خاطر دا ځای ناپاکه شوی او بلکل به له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_10.mp3', '', 1761754199, 1761754199),
(37345, 'Micah 2:11', 'Micah', 2, 11, 'دا خلک داسې پیغمبران غواړي چې هغه دروغجن او چلباز وي او وایي: ‹زه دا پېشګویي کوم چې په تاسو باندې به شراب رابهیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_11.mp3', '', 1761754199, 1761754199),
(37346, 'Micah 2:12', 'Micah', 2, 12, 'څښتن وایي:« خو ای د اسراییلو هغو خلکو چې ژوندي پاتې یئ، زه به تاسو سره راټول کړم. زه به تاسو داسې سره راټول کړم لکه پسونه چې پنډغالي ته راټولیږي. ستاسو وطن به د ډېرو خلکو د شور‌ماشور نه بیا داسې ډک شي لکه څنګه چې څړځای د ډېرو پسونو نه ډک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_12.mp3', '', 1761754199, 1761754199),
(37347, 'Micah 2:13', 'Micah', 2, 13, 'زه به د هغوی دپاره یوه لاره خلاصه کړم او هغوی ته به د جلاوطنۍ نه د راوتلو لاره وښایم. هغوی به د ښار دروازې ماتې کړي او وبه وځي. د هغوی پاچا چې څښتن دی، د هغوی نه به مخکې روان وي او په خپله به د هغوی لارښوونه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah2_verse_13.mp3', '', 1761754199, 1761754199),
(37348, 'Job 31:1', 'Job', 31, 1, 'ما د خپل ځان سره يو لوظ کړے دے چې يوې پېغلې ته به هم په غلط نظر باندې نۀ ګورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_1.mp3', '', 1761754199, 1761754199),
(37349, 'Job 31:2', 'Job', 31, 2, 'پاس په آسمان کښې خُدائ پاک به زما دپاره څۀ کوى، او په قادر خُدائ کښې به زما ميراث څۀ وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_2.mp3', '', 1761754199, 1761754199),
(37350, 'Job 31:3', 'Job', 31, 3, 'افت په ګناهګارو خلقو نۀ راغورزيږى څۀ، او مصيبت په هغه خلقو چې څوک بدعمله وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_3.mp3', '', 1761754199, 1761754199),
(37351, 'Job 31:4', 'Job', 31, 4, 'زۀ چې څۀ هم کوم نو هغۀ ته پته ده، او زما په هر قدم باندې يې نظر دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_4.mp3', '', 1761754199, 1761754199),
(37352, 'Job 31:5', 'Job', 31, 5, 'ما کله چا ته دروغ وئيلى دى څۀ، او يا مې چا له دوکه ورکړې ده څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_5.mp3', '', 1761754199, 1761754199),
(37353, 'Job 31:6', 'Job', 31, 6, 'نو زۀ دې د اِنصاف په تله کښې وتللے شم، چې خُدائ پاک ته زما د صداقت پته ولګى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_6.mp3', '', 1761754199, 1761754199),
(37354, 'Job 31:7', 'Job', 31, 7, 'کۀ زما قدم د هغۀ د لارې نه اوړېدلے وى، او زما زړۀ زما د سترګو په خواهش پسې تلے وى، يا کۀ د څۀ بل څۀ ګناه شوى وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_7.mp3', '', 1761754199, 1761754199),
(37355, 'Job 31:8', 'Job', 31, 8, 'نو ما پرېږده چې څۀ وکَرم او نور يې وخورى، او زما کَرلے فصل دې تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_8.mp3', '', 1761754199, 1761754199),
(37356, 'Job 31:9', 'Job', 31, 9, 'کۀ زۀ د ګاونډى په ښځه باندې مئين شم، او د هغې په دروازه کښې په طمع کښېنم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_9.mp3', '', 1761754199, 1761754199),
(37357, 'Job 31:10', 'Job', 31, 10, 'نو بيا دې زما ښځه د نورو دپاره مېچن وکړى، او پرېږده چې نور سړى د هغې سره څملى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_10.mp3', '', 1761754199, 1761754199),
(37358, 'Job 31:11', 'Job', 31, 11, 'ځکه چې دا به د شرم نه ډک کار وى، او دا به د سزا حقدار جرم وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_11.mp3', '', 1761754199, 1761754199),
(37359, 'Job 31:12', 'Job', 31, 12, 'ځکه چې دا به د دوزخ په شان تباه کوونکے اور وى، او زما به هر څۀ تباه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_12.mp3', '', 1761754199, 1761754199),
(37360, 'Job 31:13', 'Job', 31, 13, 'کۀ زما وينځې يا غلام ما ته شکايت کړے وى، او ما هغوئ سره اِنصاف نۀ وى کړے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_13.mp3', '', 1761754199, 1761754199),
(37361, 'Job 31:14', 'Job', 31, 14, 'نو بيا زۀ خُدائ پاک ته څنګه مخامخ کېدے شم؟ کله چې هغه حِساب کِتاب کوى نو زۀ څۀ جواب ورکړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_14.mp3', '', 1761754199, 1761754199),
(37362, 'Job 31:15', 'Job', 31, 15, 'هغه خُدائ پاک چې زۀ يې پېدا کړے يم، زما نوکران يې هم پېدا کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_15.mp3', '', 1761754199, 1761754199),
(37363, 'Job 31:16', 'Job', 31, 16, 'ما کله هم د غريبانانو مدد نۀ دے پرېښے، او نۀ مې کونډې مايُوسه کړې دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_16.mp3', '', 1761754199, 1761754199),
(37364, 'Job 31:17', 'Job', 31, 17, 'يا مې په روټۍ کښې د شومتوب نه کار اخستے وى، او دا مې يتيمانانو له نۀ وى ورکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_17.mp3', '', 1761754199, 1761754199),
(37365, 'Job 31:18', 'Job', 31, 18, 'ځکه چې د ځوانۍ نه ما د يتيمانانو خيال لکه د يو پلار په شان ساتلے دے، او ټول عُمر مې په کونډو پام کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_18.mp3', '', 1761754199, 1761754199),
(37366, 'Job 31:19', 'Job', 31, 19, 'کۀ ما څوک په تکليف کښې ليدلے وى چې جامې يې نۀ وى، يا دومره غريب وى چې جامې نۀ شى اخستے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_19.mp3', '', 1761754199, 1761754199),
(37367, 'Job 31:20', 'Job', 31, 20, 'نو ما ورله د کپړو دپاره د خپلو ګډو وړئ ورکړې ده چې ځان په کښې ګرم کړى، او هغوئ زما شکريه ادا کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_20.mp3', '', 1761754199, 1761754199),
(37368, 'Job 31:21', 'Job', 31, 21, 'کۀ ما د يتيمانانو خِلاف خپل لاس اوچت کړے وى، ځکه چې ما ته پته وه چې په عدالت کښې زما ملګرى شته دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_21.mp3', '', 1761754199, 1761754199),
(37369, 'Job 31:22', 'Job', 31, 22, 'نو زما لاسونه دې مات شى، او زما د تن نه دې پرې کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_22.mp3', '', 1761754199, 1761754199),
(37370, 'Job 31:23', 'Job', 31, 23, 'ځکه چې زۀ د خُدائ پاک د مصيبت نه په يره کښې وم، او زۀ د هغۀ د شان او شوکت په وړاندې نۀ شوم ودرېدلے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_23.mp3', '', 1761754199, 1761754199),
(37371, 'Job 31:24', 'Job', 31, 24, 'کۀ ما په سرو زرو يقين کړے وے، يا مې په سوچه سرو زرو باندې اعتبار کړے وے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_24.mp3', '', 1761754199, 1761754199),
(37372, 'Job 31:25', 'Job', 31, 25, 'کۀ ما د خپل مال دولت په وجه خوشحالى کړے وے، يا چې ما سره ډېر څۀ دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_25.mp3', '', 1761754199, 1761754199),
(37373, 'Job 31:26', 'Job', 31, 26, 'کۀ ما په هغه وخت کښې نمر ته کتلے په کوم وخت کښې چې دا ځلېدو، يا مې سپوږمۍ ته کتلے چې د شان او شوکت سره روانه وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_26.mp3', '', 1761754199, 1761754199),
(37374, 'Job 31:27', 'Job', 31, 27, 'او کۀ زما زړۀ په پټه د دې عبادت شروع کړے وے، او د دُعا دپاره مې ورته لاسونه اوچت کړے وے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_27.mp3', '', 1761754199, 1761754199),
(37375, 'Job 31:28', 'Job', 31, 28, 'دا به يو غلطى وے او قاضيانو به د دې په وجه سزا راکړے وے، ځکه چې زۀ به د خُدائ تعالىٰ مجرم وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_28.mp3', '', 1761754199, 1761754199),
(37376, 'Job 31:29', 'Job', 31, 29, 'کۀ زۀ د هغه خلقو په تباهۍ باندې خوشحاله وے چا چې زما نه نفرت کولو، يا مې په هغه وخت کښې خوشحالى کولے چې بدعملى په هغوئ باندې غالِبه شوې وه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_29.mp3', '', 1761754199, 1761754199),
(37377, 'Job 31:30', 'Job', 31, 30, 'ما په خپله خولۀ باندې داسې ګناه نۀ ده کړې چې هغوئ ته مې د مرګ ښېرې کړے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_30.mp3', '', 1761754199, 1761754199),
(37378, 'Job 31:31', 'Job', 31, 31, 'زما په خاندان کښې هر يو کس ته پته ده، چې زما کور ته څوک هم راغلى دى نو د هغوئ ښۀ مېلمستيا شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_31.mp3', '', 1761754199, 1761754199),
(37379, 'Job 31:32', 'Job', 31, 32, 'ما په پردو خلقو هيڅکله بې‌غورى نۀ ده کړې چې هغوئ په کوڅه کښې شپه تېره کړى، او ما مسافرو ته خپلې دروازې کولاو ساتلې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_32.mp3', '', 1761754199, 1761754199),
(37380, 'Job 31:33', 'Job', 31, 33, 'کۀ ما خپله ګناه د نورو خلقو په شان پټه کړې وې، او غلطى مې په خپل زړۀ کښې پټه ساتلې وې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_33.mp3', '', 1761754199, 1761754199),
(37381, 'Job 31:34', 'Job', 31, 34, 'ځکه چې زۀ د ګڼې نه يا د خلقو د بې‌عزتۍ نه يرېدلے يم، چې غلے پاتې يم او د کور نه نۀ يم وتلے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_34.mp3', '', 1761754199, 1761754199),
(37382, 'Job 31:35', 'Job', 31, 35, 'نو اے کاش چې ما ته چا غوږ نيولے وے. زۀ ليکلى درکوم چې هره يوه خبره رښتيا ده. او قادر خُدائ دې زما فرياد واورى، او زما مخالفين دې ليکلے اِلزام راوړى چې زۀ يې وګورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_35.mp3', '', 1761754199, 1761754199),
(37383, 'Job 31:36', 'Job', 31, 36, 'بې‌شکه زۀ به په فخر سره د اِلزام مقابله وکړم او زۀ به دا د تاج په شان په سر کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_36.mp3', '', 1761754199, 1761754199),
(37384, 'Job 31:37', 'Job', 31, 37, 'زۀ به هغۀ له د خپل عمل حِساب کِتاب ورکړم، او د هغۀ په حضور کښې به زړَور ولاړ يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_37.mp3', '', 1761754199, 1761754199),
(37385, 'Job 31:38', 'Job', 31, 38, 'کۀ ما هغه زمکه قبضه کړې وى چې کومه زۀ کرَم او دا مې د خپل اصلى مالِک نه اخستې وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_38.mp3', '', 1761754199, 1761754199),
(37386, 'Job 31:39', 'Job', 31, 39, 'کۀ د دې پېداوار ما بغېر د پېسو نه خوړلے وى، او کۀ ما د دې مالِکان وژلى وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_39.mp3', '', 1761754199, 1761754199),
(37387, 'Job 31:40', 'Job', 31, 40, 'نو پرېږده چې د غنمو په ځائ ازغى وشى، او د اوربشو په ځائ دې ګنده واښۀ وشى.“ د ايُوب خبرې ختمې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job31_verse_40.mp3', '', 1761754199, 1761754199),
(37388, 'Isaiah 54:1', 'Isaiah', 54, 1, 'څښتن وایي: «ای اورشلیمه، ته وې په شان د هغې شنډې ښځې چې دردونه یې د لنګون نه وي لیدلي خو اوس ووایه د خوشحالۍ سندرې او ووهه چیغې په لوړ اواز! سره له دې چې شړل شوې وې ته خو ته به د مېړه لرونکې ښځې څخه ولرې زیات اولادونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_1.mp3', '', 1761754199, 1761754199),
(37389, 'Isaiah 54:2', 'Isaiah', 54, 2, 'کومه خېمه کې چې اوسېږې هغه لویه کړه ته پردې یې جوړې کړه خورې ورې په مصرف کې یې سپما مه کوه رسۍ ګانې کړه اوږدې د هغې او ښه یې کلکه کړه مېخونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_2.mp3', '', 1761754199, 1761754199),
(37390, 'Isaiah 54:3', 'Isaiah', 54, 3, 'هرې خواته به ته وغزوې خپلې پولې کومه ځمکه چې نیولې ده اوس نورو خلکو بېرته به یې ونیسي اولاده ستاسو کوم ښارونه چې اوس وران دي هغه به بېرته کړي ودان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_3.mp3', '', 1761754199, 1761754199),
(37391, 'Isaiah 54:4', 'Isaiah', 54, 4, 'مه وېرېږه، ځکه ته به مخامخ نه شې بیا له رسوایۍ سره مه بې زړه کېږه، ځکه رسوا به نه شې ځکه چې هېر به کړې ته شرم د خپلې ځوانۍ او وبه نه وینې ته سپکاوی د کونډتوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_4.mp3', '', 1761754199, 1761754199),
(37392, 'Isaiah 54:5', 'Isaiah', 54, 5, 'ځکه ستا خالق چې نوم یې دی مطلق قادر څښتن ستا دپاره هغه دی لکه مېړه په شان سپېڅلی خدای د اسراییلو دی ژغورونکی ستا هغه ته وایي خدای د ټولې نړۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_5.mp3', '', 1761754199, 1761754199),
(37393, 'Isaiah 54:6', 'Isaiah', 54, 6, 'ته یې د ځوانې ښځې په شان چې پریښې یې وي مېړه او مات شوی یې وي زړه خو ستا څښتن خدای بېرته راغواړي تا او داسې وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_6.mp3', '', 1761754199, 1761754199),
(37394, 'Isaiah 54:7', 'Isaiah', 54, 7, '‹ما ته پرېښودلې د ډېر لږ وخت دپاره خو اوس به زه په ډېره مینه بېرته تا راولم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_7.mp3', '', 1761754199, 1761754199),
(37395, 'Isaiah 54:8', 'Isaiah', 54, 8, 'ډېرې غوسې نه ما مخ واړاوه له تا یوې شېبې دپاره خو زه به رحم وکړم تا باندې تلپاتې مینې سره›» هغه څښتن چې ستا ژغورونکی دی، داسې وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_8.mp3', '', 1761754199, 1761754199),
(37396, 'Isaiah 54:9', 'Isaiah', 54, 9, '«ځکه دا زما دپاره ده لکه د نوح د زمانې په شان لکه څنګه چې ځمکه ونیوله ټوله اوبو او په هغه وخت کې مې خوړلی ؤ قسم بیا به هېڅکله رانه شي داسې سېلاب په ځمکه اوس هم قسم خورم چې بیا به نه شمه په تا باندې په قهر او تاته نه درکوم نوره سزا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_9.mp3', '', 1761754199, 1761754199),
(37397, 'Isaiah 54:10', 'Isaiah', 54, 10, 'که له منځه لاړ شي غرونه او له خپله ځایه شي غونډۍ بېځایه خو لاړه به نه شي له منځه زما تلپاتې مینه او د تل دپاره به ولاړ یم د خپلې سولې په لوظ» هغه څښتن چې کوي رحم په تا، دا وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_10.mp3', '', 1761754199, 1761754199),
(37398, 'Isaiah 54:11', 'Isaiah', 54, 11, 'څښتن وایي: «ای کړېدلیه ښاره چې تېر شوی دی توفان درباندې هېڅوک نشته چې تاته درکړي تسلي ګوره، زه به تا بېرته جوړ کړم د قیمتي تیږو نه او بنیادونه به دې کېږدم د لاجوردو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_11.mp3', '', 1761754199, 1761754199),
(37399, 'Isaiah 54:12', 'Isaiah', 54, 12, 'د یاقوتو نه به جوړ کړم ستا برجونه او دروازې به دې وي د هغو تیږو چې ځلیږي له قیمتي تیږو به جوړ کړم ستا شاوخوا دېوالونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_12.mp3', '', 1761754199, 1761754199),
(37400, 'Isaiah 54:13', 'Isaiah', 54, 13, 'زه به په خپله تعلیم ورکړم ټولو اولادونو ته ستا او ور په برخه به کړم سوله او ارامي ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_13.mp3', '', 1761754199, 1761754199),
(37401, 'Isaiah 54:14', 'Isaiah', 54, 14, 'ستا بنیاد به وي ولاړ په عدالت او انصاف ته به لېرې یې له ظلمه او وبه نه وېرېږې او نه به وېره تاته راشي نژدې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_14.mp3', '', 1761754199, 1761754199),
(37402, 'Isaiah 54:15', 'Isaiah', 54, 15, 'که چېرې څوک جګړه وکړي له تا سره اراده به زما نه وي په هغه کې څوک چې جګړه کوي له تا سره هغه به ماتې وخوري ستا له امله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_15.mp3', '', 1761754199, 1761754199),
(37403, 'Isaiah 54:16', 'Isaiah', 54, 16, 'ګوره، ما پیدا کړی اهنګر دی چې په اورغالي کې سکاره بلوي په پکي باندې او وسله جوړوي د خپل مقصد دپاره او هم مې پیدا کړ تباه کوونکی چې کار واخلي له وسلې نه د تباهۍ په خاطر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_16.mp3', '', 1761754199, 1761754199),
(37404, 'Isaiah 54:17', 'Isaiah', 54, 17, 'کومه وسله چې ستا په ضد جوړیږي تاته نه شي رسولی ضرر چې په تا باندې څوک تور لګوي ته بریالی به شې هغه باندې خادمان به زما ګټه واخلي دې نه او ور په برخه به بری کړمه هغوی ته» دا د څښتن وینا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah54_verse_17.mp3', '', 1761754199, 1761754199),
(37405, 'Isaiah 63:1', 'Isaiah', 63, 1, 'دا څوک دی چې د ادوم د بزرې د ښار څخه راروان دی او تک سره کالي یې اغوستي دي؟ دا څوک دی چې شانداره کالي لري او په لوی قدرت سره راروان دی؟ «دا زه څښتن یم چې د ژغورلو وس لرم او راروان یم چې خپل بریالیتوب اعلان کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_1.mp3', '', 1761754199, 1761754199),
(37406, 'Isaiah 63:2', 'Isaiah', 63, 2, 'ولې ستا کالي سره دي، داسې دي لکه چا چې د شرابو د جوړولو په خاطر انګور د پښو لاندې کړي وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_2.mp3', '', 1761754199, 1761754199),
(37407, 'Isaiah 63:3', 'Isaiah', 63, 3, 'څښتن ځواب ورکوي: «هو، ما یوازې او پرته د چا له مرستې د غوسې په وخت کې خلک د انګورو په شان تر پښو لاندې کړل او د هغوی وینې زما کالي سره کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_3.mp3', '', 1761754199, 1761754199),
(37408, 'Isaiah 63:4', 'Isaiah', 63, 4, 'ځکه ما پرېکړه وکړه، هغه وخت رارسېدلی دی چې د خپلو دښمنانو څخه بدل واخلم او خپل قوم وژغورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_4.mp3', '', 1761754199, 1761754199),
(37409, 'Isaiah 63:5', 'Isaiah', 63, 5, 'هرې خواته مې وکتل چې څوک پیدا کړم، ترڅو زما سره مرسته وکړي. په حیرانتیا سره مې ولیدل چې مرسته کوونکی نشته، نو بیا د خپل قدرت او قهر په مرسته بریالی شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_5.mp3', '', 1761754199, 1761754199),
(37410, 'Isaiah 63:6', 'Isaiah', 63, 6, 'ما په خپل قهر سره قومونه تر پښو لاندې کړل او هغوی مې د یو نشه سړي په شان کړل، بیا مې د هغوی وینه په ځمکه تویه کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah63_verse_6.mp3', '', 1761754199, 1761754199);